educes a target's HP.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local damage = xi.spells.damage.useDamageSpell(caster, target, spell) -- Gets nuke power and sets messages.\n\n    -- Can't apply if absorbed or nullified.\n    if damage > 0 then\n        local power    = utils.clamp(damage, 0, 9999)\n        local duration = xi.spells.enfeebling.calculateDuration(caster, target, spell:getID(), xi.effect.HELIX, xi.skill.ELEMENTAL_MAGIC)\n\n        target:addStatusEffect(xi.effect.HELIX, { power = power, duration = duration, origin = caster, tick = 10, tier = 1 })\n    end\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/geohelix_ii.lua"]={["Path"]="scripts/actions/spells/black/geohelix_ii.lua",["SHA256"]="fabd145b3327836c903d6e1ac8b22208b4261e1c9a1cb6a0d481432989591813",["Text"]="-----------------------------------\n-- Spell: Geohelix II\n-- Deals earth damage that gradually reduces a target's HP.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local damage = xi.spells.damage.useDamageSpell(caster, target, spell) -- Gets nuke power and sets messages.\n\n    -- Can't apply if absorbed or nullified.\n    if damage > 0 then\n        local power    = utils.clamp(damage, 0, 9999)\n        local duration = xi.spells.enfeebling.calculateDuration(caster, target, spell:getID(), xi.effect.HELIX, xi.skill.ELEMENTAL_MAGIC)\n\n        target:addStatusEffect(xi.effect.HELIX, { power = power, duration = duration, origin = caster, tick = 10, tier = 2 })\n    end\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/graviga.lua"]={["Path"]="scripts/actions/spells/black/graviga.lua",["SHA256"]="e4c1342f418a8f2497b7d8a2c71f32152839f119f55b40c3cc8e80528cf17b37",["Text"]="-----------------------------------\n-- Spell: Gravity\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.enfeebling.useEnfeeblingSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/gravity.lua"]={["Path"]="scripts/actions/spells/black/gravity.lua",["SHA256"]="e4c1342f418a8f2497b7d8a2c71f32152839f119f55b40c3cc8e80528cf17b37",["Text"]="-----------------------------------\n-- Spell: Gravity\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.enfeebling.useEnfeeblingSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/gravity_ii.lua"]={["Path"]="scripts/actions/spells/black/gravity_ii.lua",["SHA256"]="e8f7e7f294fe2a77f458efe1c55e754f18032060669921794e8c6aacbb1ede74",["Text"]="-----------------------------------\n-- Spell: Gravity II\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.enfeebling.useEnfeeblingSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/hydrohelix.lua"]={["Path"]="scripts/actions/spells/black/hydrohelix.lua",["SHA256"]="2e1968b9ee914ddb39656eca8e91540b987720a6a1c1e514b53da83ccadb0b1e",["Text"]="-----------------------------------\n-- Spell: Hydrohelix\n-- Deals water damage that gradually reduces a target's HP.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local damage = xi.spells.damage.useDamageSpell(caster, target, spell) -- Gets nuke power and sets messages.\n\n    -- Can't apply if absorbed or nullified.\n    if damage > 0 then\n        local power    = utils.clamp(damage, 0, 9999)\n        local duration = xi.spells.enfeebling.calculateDuration(caster, target, spell:getID(), xi.effect.HELIX, xi.skill.ELEMENTAL_MAGIC)\n\n        target:addStatusEffect(xi.effect.HELIX, { power = power, duration = duration, origin = caster, tick = 10, tier = 1 })\n    end\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/hydrohelix_ii.lua"]={["Path"]="scripts/actions/spells/black/hydrohelix_ii.lua",["SHA256"]="35965b8e53327d3c27a8d729776eade431b980a7656671660931b175dc31300b",["Text"]="-----------------------------------\n-- Spell: Hydrohelix II\n-- Deals water damage that gradually reduces a target's HP.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local damage = xi.spells.damage.useDamageSpell(caster, target, spell) -- Gets nuke power and sets messages.\n\n    -- Can't apply if absorbed or nullified.\n    if damage > 0 then\n        local power    = utils.clamp(damage, 0, 9999)\n        local duration = xi.spells.enfeebling.calculateDuration(caster, target, spell:getID(), xi.effect.HELIX, xi.skill.ELEMENTAL_MAGIC)\n\n        target:addStatusEffect(xi.effect.HELIX, { power = power, duration = duration, origin = caster, tick = 10, tier = 2 })\n    end\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/ice_spikes.lua"]={["Path"]="scripts/actions/spells/black/ice_spikes.lua",["SHA256"]="efdee39621c7d2e5bce43f079057549b1879b2577168b7d8e14c127fac76aa36",["Text"]="-----------------------------------\n-- Spell: Ice Spikes\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.enhancing.useEnhancingSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/impact.lua"]={["Path"]="scripts/actions/spells/black/impact.lua",["SHA256"]="bec98605643751609b755999e34f78fa4aa4db19678f7a6a9be5edf1fcafb7cf",["Text"]="-----------------------------------\n-- Spell: Impact\n-- Deals dark damage to an enemy and\n-- decreases all 7 base stats by 20%\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local damage = xi.spells.damage.useDamageSpell(caster, target, spell)\n\n    -- Apply effects.\n    local effectTable =\n    {\n        [1] = { xi.effect.STR_DOWN, xi.mod.STR },\n        [2] = { xi.effect.DEX_DOWN, xi.mod.DEX },\n        [3] = { xi.effect.VIT_DOWN, xi.mod.VIT },\n        [4] = { xi.effect.AGI_DOWN, xi.mod.AGI },\n        [5] = { xi.effect.INT_DOWN, xi.mod.INT },\n        [6] = { xi.effect.MND_DOWN, xi.mod.MND },\n        [7] = { xi.effect.CHR_DOWN, xi.mod.CHR },\n    }\n\n    local params =\n    {\n        magicalElement = xi.element.DARK,\n        actorStat      = xi.mod.INT,\n        skillType      = xi.skill.ELEMENTAL_MAGIC,\n        spellGroup     = spell:getSpellGroup(),\n    }\n\n    local resist = xi.combat.magicHitRate.calculateResistRate(caster, target, params)\n\n    for i = 1, 7 do\n        local effectId = effectTable[i][1]\n        if not target:hasStatusEffect(effectId) then\n            local power    = math.floor(target:getStat(effectTable[i][2]) / 5)\n            local duration = math.floor(180 * resist)\n            target:addStatusEffect(effectId, { power = power, duration = duration, origin = caster })\n        end\n    end\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/ionohelix.lua"]={["Path"]="scripts/actions/spells/black/ionohelix.lua",["SHA256"]="c7fab2b3e6a89a467440c51b82d84d4fb8d7c7f9186169ca874c25e85b3e462e",["Text"]="-----------------------------------\n-- Spell: Ionohelix\n-- Deals lightning damage that gradually reduces a target's HP.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local damage = xi.spells.damage.useDamageSpell(caster, target, spell) -- Gets nuke power and sets messages.\n\n    -- Can't apply if absorbed or nullified.\n    if damage > 0 then\n        local power    = utils.clamp(damage, 0, 9999)\n        local duration = xi.spells.enfeebling.calculateDuration(caster, target, spell:getID(), xi.effect.HELIX, xi.skill.ELEMENTAL_MAGIC)\n\n        target:addStatusEffect(xi.effect.HELIX, { power = power, duration = duration, origin = caster, tick = 10, tier = 1 })\n    end\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/ionohelix_ii.lua"]={["Path"]="scripts/actions/spells/black/ionohelix_ii.lua",["SHA256"]="413fd421ff07a53f980ab0e6c7c60a26c2a0fd64448aee9005903546a1089bdd",["Text"]="-----------------------------------\n-- Spell: Ionohelix II\n-- Deals lightning damage that gradually reduces a target's HP.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local damage = xi.spells.damage.useDamageSpell(caster, target, spell) -- Gets nuke power and sets messages.\n\n    -- Can't apply if absorbed or nullified.\n    if damage > 0 then\n        local power    = utils.clamp(damage, 0, 9999)\n        local duration = xi.spells.enfeebling.calculateDuration(caster, target, spell:getID(), xi.effect.HELIX, xi.skill.ELEMENTAL_MAGIC)\n\n        target:addStatusEffect(xi.effect.HELIX, { power = power, duration = duration, origin = caster, tick = 10, tier = 2 })\n    end\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/kaustra.lua"]={["Path"]="scripts/actions/spells/black/kaustra.lua",["SHA256"]="b823770686dd0ed5b1d1c3c93642c0f29af01ca7a7a2859029cca76037203725",["Text"]="-----------------------------------\n-- Spell: Kaustra\n-- Consumes 20% of your maximum MP.\n-- Relentless dark damage slowly devours an enemy.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    if caster:hasStatusEffect(xi.effect.TABULA_RASA) then\n        return 0\n    end\n\n    return 1\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local damage = xi.spells.damage.useDamageSpell(caster, target, spell) -- Gets nuke power and sets messages.\n\n    -- Can't apply if absorbed, nullified or 0 power.\n    if damage >= 4 then\n        local casterSkill = utils.clamp(caster:getSkillLevel(xi.skill.DARK_MAGIC), 0, 500)\n        local power       = math.floor(damage / 4)\n        local duration    = math.floor(3 * (1 + casterSkill / 11))\n\n        target:addStatusEffect(xi.effect.KAUSTRA, { power = power, duration = duration, origin = caster, tick = 3 })\n    end\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/klimaform.lua"]={["Path"]="scripts/actions/spells/black/klimaform.lua",["SHA256"]="adbf7cb538a53b2b914e02c044c28ffbcb5559b9eed73ffc77110d284e89b956",["Text"]="-----------------------------------\n-- Spell: Klimaform\n-- Increases magic accuracy for spells of the same element as current weather\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    target:addStatusEffect(xi.effect.KLIMAFORM, { power = 1, duration = 180, origin = caster })\n\n    return xi.effect.KLIMAFORM\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/luminohelix.lua"]={["Path"]="scripts/actions/spells/black/luminohelix.lua",["SHA256"]="c71ba84dc845563bf6db7b41605d7189dc9044c27c0fd964ac66b3215278d05a",["Text"]="-----------------------------------\n-- Spell: Luminohelix\n-- Deals light damage that gradually reduces a target's HP.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local damage = xi.spells.damage.useDamageSpell(caster, target, spell) -- Gets nuke power and sets messages.\n\n    -- Can't apply if absorbed or nullified.\n    if damage > 0 then\n        local power    = utils.clamp(damage, 0, 9999)\n        local duration = xi.spells.enfeebling.calculateDuration(caster, target, spell:getID(), xi.effect.HELIX, xi.skill.ELEMENTAL_MAGIC)\n\n        target:addStatusEffect(xi.effect.HELIX, { power = power, duration = duration, origin = caster, tick = 10, tier = 1 })\n    end\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/luminohelix_ii.lua"]={["Path"]="scripts/actions/spells/black/luminohelix_ii.lua",["SHA256"]="a483cb2ee8409a81e0a49af5394af2bfeade5e2d61d9d442f01dc2777b055869",["Text"]="-----------------------------------\n-- Spell: Luminohelix II\n-- Deals light damage that gradually reduces a target's HP.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local damage = xi.spells.damage.useDamageSpell(caster, target, spell) -- Gets nuke power and sets messages.\n\n    -- Can't apply if absorbed or nullified.\n    if damage > 0 then\n        local power    = utils.clamp(damage, 0, 9999)\n        local duration = xi.spells.enfeebling.calculateDuration(caster, target, spell:getID(), xi.effect.HELIX, xi.skill.ELEMENTAL_MAGIC)\n\n        target:addStatusEffect(xi.effect.HELIX, { power = power, duration = duration, origin = caster, tick = 10, tier = 2 })\n    end\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/meteor.lua"]={["Path"]="scripts/actions/spells/black/meteor.lua",["SHA256"]="2485cf35afd6b21cb238c90e34dcb7c4b410bd6f96b48fe0d4dd09e78c41872d",["Text"]="-----------------------------------\n-- Spell: Meteor\n-- Deals non-elemental damage to an enemy.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    -- TODO: Correct message is \"Incorrect job, job level too low, or required ability not activated.\"  Unable to locate this in our basic or system message functions.\n    -- The client blocks the spell via menus, but it can still be cast via text commands, so we have to block it here, albiet with the wrong message.\n    if caster:isMob() then\n        return 0\n    elseif caster:hasStatusEffect(xi.effect.ELEMENTAL_SEAL) then\n        return 0\n    else\n        return xi.msg.basic.STATUS_PREVENTS\n    end\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    --calculate raw damage\n    --Byrthnoth @ Random Facts Thread: Magic @ BG:\n    --Spell Base Damage = MAB/MDB*floor(Int + Elemental Magic Skill/6)*3.5\n    --NOT AFFECTED BY DARK BONUSES (bonus ETC)\n    --I'll just point this out again. It can't resist, there's no dINT, and the damage is non-elemental. The only terms that affect it for monsters (that we know of) are MDB and MDT. If a --normal monster would take 50k damage from your group, Botulus would take 40k damage. Every. Time.\n    local damage = 0\n    if caster:isPC() then\n        damage = ((100 + caster:getMod(xi.mod.MATT)) / (100 + target:getMod(xi.mod.MDEF))) * (caster:getStat(xi.mod.INT) + caster:getSkillLevel(xi.skill.ELEMENTAL_MAGIC) / 6) * 3.5\n    elseif caster:getFamily() == xi.mobFamily.BEHEMOTH then -- Behemoth family\n        -- Not entirely accurate until mobspell skills are reworked. #7222\n        -- TODO: + dINT *2 until dINT +13. When dINT is negative, dINT / 2 until unknown floor.\n        -- TODO: Account for all mitigation sources.\n        -- TODO: Account for rage.\n        damage = caster:getMainLvl() * 15.5\n    elseif caster:getSpecies() == xi.mobSpecies.PROMATHIA then -- Promathia family\n        damage = caster:getMainLvl() * 7\n    else\n        damage = ((100 + caster:getMod(xi.mod.MATT)) / (100 + target:getMod(xi.mod.MDEF))) * (caster:getStat(xi.mod.INT) + (caster:getMaxSkillLevel(caster:getMainLvl(), xi.job.BLM, xi.skill.ELEMENTAL_MAGIC)) / 6) * 9.4\n    end\n\n    damage = math.floor(damage * xi.spells.damage.calculateAbsorption(target, xi.element.NONE, false, true, false, false))\n    damage = math.floor(damage * xi.spells.damage.calculateNullification(target, xi.element.NONE, false, true, false, false))\n    damage = math.floor(damage * xi.spells.damage.calculateMTDR(caster, spell))\n    damage = math.floor(damage * xi.combat.damage.calculateDamageAdjustment(target, false, true, false, false))\n\n    -- Handle Phalanx, One for All, Stoneskin.\n    damage = utils.clamp(utils.handlePhalanx(target, damage), 0, 99999)\n    damage = utils.clamp(utils.handleOneForAll(target, damage), 0, 99999)\n    damage = utils.handleStoneskin(target, damage, xi.attackType.MAGICAL)\n\n    -- Handle final adjustments. Most are located in core. TODO: Decide if we want core handling this.\n    -- Check if the mob has a damage cap\n    damage = target:checkDamageCap(damage)\n\n    -- Handle Bind break and TP?\n    target:takeSpellDamage(caster, spell, damage, xi.attackType.MAGICAL, xi.damageType.ELEMENTAL)\n\n    -- Handle Afflatus Misery.\n    target:handleAfflatusMiseryDamage(damage)\n\n    -- Handle Enmity.\n    target:updateEnmityFromDamage(caster, damage)\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/noctohelix.lua"]={["Path"]="scripts/actions/spells/black/noctohelix.lua",["SHA256"]="d18c8f9b061d24642ddc7dac03a3d070834046daf3f00fcd62517eb9099b0c0c",["Text"]="-----------------------------------\n-- Spell: Noctohelix\n-- Deals dark damage that gradually reduces a target's HP.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local damage = xi.spells.damage.useDamageSpell(caster, target, spell) -- Gets nuke power and sets messages.\n\n    -- Can't apply if absorbed or nullified.\n    if damage > 0 then\n        local power    = utils.clamp(damage, 0, 9999)\n        local duration = xi.spells.enfeebling.calculateDuration(caster, target, spell:getID(), xi.effect.HELIX, xi.skill.ELEMENTAL_MAGIC)\n\n        target:addStatusEffect(xi.effect.HELIX, { power = power, duration = duration, origin = caster, tick = 10, tier = 1 })\n    end\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/noctohelix_ii.lua"]={["Path"]="scripts/actions/spells/black/noctohelix_ii.lua",["SHA256"]="b34f9af8da822c817858095a76c14b9ebf0d8af0f7d76bdc3b4370e5cad42d52",["Text"]="-----------------------------------\n-- Spell: Noctohelix II\n-- Deals dark damage that gradually reduces a target's HP.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local damage = xi.spells.damage.useDamageSpell(caster, target, spell) -- Gets nuke power and sets messages.\n\n    -- Can't apply if absorbed or nullified.\n    if damage > 0 then\n        local power    = utils.clamp(damage, 0, 9999)\n        local duration = xi.spells.enfeebling.calculateDuration(caster, target, spell:getID(), xi.effect.HELIX, xi.skill.ELEMENTAL_MAGIC)\n\n        target:addStatusEffect(xi.effect.HELIX, { power = power, duration = duration, origin = caster, tick = 10, tier = 2 })\n    end\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/poison.lua"]={["Path"]="scripts/actions/spells/black/poison.lua",["SHA256"]="4c40eaf5dd8b0220e019765a2bd4c765e98491f7771d860ca92a3873141c8c27",["Text"]="-----------------------------------\n--   Spell: Poison\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.enfeebling.useEnfeeblingSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/poison_ii.lua"]={["Path"]="scripts/actions/spells/black/poison_ii.lua",["SHA256"]="eb5bb5afbb312326ed865908766b4e88a3c642c80425d315097a49248e7ac991",["Text"]="-----------------------------------\n-- Spell: Poison II\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.enfeebling.useEnfeeblingSpell(caster, target, spell)\nend\n\nreturn spellObject\n"}};
